def fibonacci(n):
    if n < 0:
        raise ValueError('fibonacci undefined for negative n')
    def mul(m1, m2):
        return [
            [m1[0][0] * m2[0][0] + m1[0][1] * m2[1][0], m1[0][0] * m2[0][1] + m1[0][1] * m2[1][1]],
            [m1[1][0] * m2[0][0] + m1[1][1] * m2[1][0], m1[1][0] * m2[0][1] + m1[1][1] * m2[1][1]],
        ]
    result = [[1, 0], [0, 1]]
    base = [[1, 1], [1, 0]]
    e = n
    while e:
        if e & 1:
            result = mul(result, base)
        base = mul(base, base)
        e >>= 1
    return result[0][1]

def run_length_encode(xs):
    if not xs:
        return []
    out = []
    cur, count = xs[0], 1
    for x in xs[1:]:
        if x == cur:
            count += 1
        else:
            out.append((cur, count))
            cur, count = x, 1
    out.append((cur, count))
    return out

